P=[['拉丁 plūs，属格 plūris','更多；比较意义上的数量增加']]
PL=P+[['拉丁 pluralis → 古法语 plurel／直接借拉丁 → 中古英语 plural','属于多个的 → 语法复数；不止一个']]
D=[['拉丁 duo“二” + 倍数后缀 -plus → duplus','两倍的、双重的'],['古法语 doble → 中古英语 double','双的、两倍的']]
TR=[['拉丁 tri-“三” + 倍数后缀 -plus → triplus','三倍的、三重的'],['古法语 triple／直接拉丁 → 中古英语 triple','三倍的；含三个部分的']]
def A(h,a,b):return h+[[a,b]]
W=[
E('double','/ˈdʌbəl/','两倍的；双重的；加倍；替身；双份','一份变成同样大的两份，或一个位置出现相配的两个。数量、用途和角色都可以沿这个画面展开。','拉丁 duplus 是 duo 二 + 倍数后缀 -plus，经法语形成形容词；动词另经 duplare → dobler 借入。不是英语 two 加独立 plus“加号”。',D+[['旁支：拉丁 duplare → 古法语 dobler → 英语 double〔动词〕','使成两倍；后来也可兼任另一用途'],['英语形容词 double → 名词 double','双倍数量；相似者、替身']], 'double the amount 是把数量变为原来的两倍，即增加原数量的百分之百。a room that doubles as an office 是一个房间兼作办公室。a stunt double 是代演员完成特技的替身。','double the price；double in size；double as；a stunt double。','twice 常放在 as…as 等比较结构中；double 可直接接数量名词。double 与 dual 都有二，但 dual 更常强调两个方面或组成。',('The number of visitors doubled from fifty to one hundred.','参观人数从五十人增加到一百人，翻了一倍。'),('The spare room doubles as a home office.','空房间兼作家庭办公室。'),('The actor used a stunt double for the dangerous jump.','演员在危险的跳跃场景中使用了特技替身。'),sources=['https://www.etymonline.com/word/double','https://www.etymonline.com/word/-plus']),
E('plus','/plʌs/','加；加号；额外的；有利因素','原本已经有一份，再往上加一点；把这个“多出来”放在计算里是加法，放在评价里是优点。','借拉丁 plūs“更多”，先后发展出数学符号的读法、额外数量和优势等意思。英语连用法并不都在古典拉丁中原样存在。',A(P,'英语 plus','加法；附加数量；有利因素'),'Three plus two is five 读加法；a big plus 是一个明显优势；people aged sixty plus 指六十岁及以上的人。看到价格后面的 plus tax，是税还需另计。','a plus sign；a big plus；plus tax；on the plus side。','extra 说额外的；plus 可直接连接计算和附加项。减法常用 minus。',('A quiet workspace is a big plus for me.','安静的工作空间对我来说是个很大的优点。'),('The price is twenty dollars plus delivery.','价格是二十美元，另加运费。'),sources=['https://www.etymonline.com/word/plus']),
E('triple','/ˈtrɪpəl/','三倍的；三重的；使增至三倍；三倍数量','拿原来那一份作单位，现在一共有同样的三份；也可以是三个层面或三个组成部分。','拉丁 triplus，tri- 三 + -plus 倍，经法语或拉丁借入形容词；动词有中世纪拉丁 triplare 的路线。',TR+[['旁支：中世纪拉丁 triplare → 英语 triple〔动词〕','使成为三倍'],['英语形容词 triple → 名词 triple','三倍数量、三件组合；另有运动专义']], 'triple the output 把产出变成原来的三倍，不是多出三倍后变成四倍。a triple role 可说一人承担三个角色；数字关系与三部分关系要看名词。','triple the amount；triple in size；a triple layer。','double 是原来的二倍，triple 是三倍；triplet 通常是三件一组，或该组中的一个。',('The new equipment tripled the workshop’s output.','新设备把车间产出提高到了原来的三倍。'),('The box has a triple layer of insulation.','箱子有三层隔热材料。'),sources=['https://www.etymonline.com/word/triple','https://www.etymonline.com/word/-plus']),
E('plural','英 /ˈplʊərəl/；美 /ˈplʊrəl/，亦有 /ˈplɜːrəl/','复数的；复数形式；多元的','把眼前对象从一个放宽到多个；语法给这种数量关系安排了相应的形式。','拉丁 plūs / plūris 更多 → pluralis，经古法语 plurel 或直接拉丁借入。plur- 是同一个拉丁词的词干形式，不是英语 plus 直接换字母。',PL,'books 是 book 的复数；children 是 child 的不规则复数。英语零数量也常接复数，如 zero errors，不能把“多于一个”当成所有句子的机械判断规则。','a plural noun；the plural of；in the plural；a plural society。','singular 指单数；plural 指复数。复数意义不保证词尾一定是 -s，sheep 的单复数形式可相同。',('The plural of child is children.','child 的复数是 children。'),('The two languages mark plural nouns in different ways.','这两种语言用不同方式标记复数名词。'),sources=['https://www.etymonline.com/word/plural','https://en.wiktionary.org/wiki/plural']),
E('plurality','英 /plʊəˈræləti/；美 /plʊˈræləti/','多个、多样性；相对多数；领先票数','一般语境是存在不止一种；票数语境是你的这一堆比任何另一堆都大，却未必超过所有票的一半。','后期拉丁 pluralitas，经古法语 pluralité 到英语；现代可对应 plural + -ity，历史名词却有独立借入路线。',P+[['拉丁 pluralis → 后期拉丁 pluralitas → 古法语 pluralité','复数、多于一个的状态'],['中古英语 pluralite → plurality','多个；后来也说相对多数与领先票数']], '三人得票四十、三十五、二十五，四十票者有 plurality，却没有过半的 majority。a plurality of views 则只说多种观点，完全不涉及投票。','a plurality of votes；win a plurality；a plurality of perspectives。','majority 通常要求超过所比较总数的一半；plurality 比较各组谁最多。具体选举是否因此当选，还由制度决定。',('She received a plurality of the votes, but not an absolute majority.','她获得了相对多数票，但没有获得绝对多数票。'),('The collection presents a plurality of views on city life.','这本文集呈现了对城市生活的多种看法。'),sources=['https://www.etymonline.com/word/plurality','https://www.merriam-webster.com/dictionary/plurality']),
E('doubly','/ˈdʌbli/','双倍地；由于两个方面而更加；格外','既可能真是两倍，也可能有两个原因叠在一起，让高兴、失望或重要性更强。','中古英语已有 doubli / dowbly，可对应 double + -ly。词干接倍数义，不是 doubt“怀疑”。',A(D,'中古英语 doubli / dowbly → doubly〔double + -ly〕','以双重方式；程度加倍地'),'doubly pleased 常表示两个好消息让人双重高兴，不是在精确测量快乐量。doubly sure 是强调特别有把握，不要求两个独立证据。','doubly important；doubly pleased；make doubly sure。','twice 多用于可比较的次数或数量；doubly 常进入抽象程度、双重原因的表达。',('She was doubly pleased because both her students had won prizes.','两个学生都获了奖，她格外高兴。'),('He checked the address again to make doubly sure.','他再次核对地址，确保万无一失。'),sources=['https://en.wiktionary.org/wiki/doubly']),
E('quadruple','英 /ˈkwɒdrʊpəl/，亦 /kwɒˈdruːpəl/；美 /kwɑːˈdruːpəl/','四倍的；四重的；增至四倍','原来一份，现在摆出同样的四份；也可说四层、四个相连部分。','拉丁 quadruplus 四倍，接四的构件和 -plus 倍。形容词、动词、名词有分别借入的路线，英语动词还早于常见形容词记录。',[['拉丁 quadri- + -plus → quadruplus / 中性 quadruplum','四倍的；四倍数量'],['法语 quadruple；拉丁 quadruplum → 英语形容词／名词 quadruple','四倍的；四倍数量'],['并行：后期拉丁 quadruplare → 法语 quadrupler → 英语动词 quadruple','使增至四倍']], '从十增加到四十就是 quadruple。运动里的 a quadruple jump 指空中四周跳，是转数应用，不等于跳得比平时高四倍。','quadruple the capacity；quadruple in size；a quadruple jump。','quadruple 表四倍；quarter 作动词可表示分成四份，动作方向相反。',('The expansion will quadruple the warehouse’s storage capacity.','扩建会使仓库的储存能力变为原来的四倍。'),('Sales quadrupled from ten units to forty units.','销量从十件增至四十件，变为原来的四倍。'),sources=['https://www.etymonline.com/word/quadruple','https://en.wiktionary.org/wiki/quadruple']),
E('pluralism','英 /ˈplʊərəlɪzəm/；美 /ˈplʊrəlɪzəm/','多元主义；多种群体、原则并存；兼任多个教职〔历史〕','一个社会或解释体系不只留一张椅子，让多个群体、观点或基本原则各有位置。','英语 plural + -ism。早期教会用法说一人兼任多个职位，后来在哲学、政治与社会讨论中分别发展多元的专义。',A(PL,'英语 plural + -ism → pluralism','兼任多个教职；多种原则、力量或群体并存的观念'),'cultural pluralism 强调不同文化群体保有特色并共同生活；哲学 pluralism 可以否认所有事物都归于唯一基本原则。不同学科的多元论不能只凭词相同就当成同一种主张。','cultural pluralism；political pluralism；value pluralism。','diversity 可以只陈述有差异；pluralism 常进一步涉及怎样承认、安排或解释这些差异。',('The essay argues for cultural pluralism in public institutions.','文章主张公共机构承认并容纳文化多元性。'),('The course contrasts philosophical pluralism with monism.','这门课比较哲学多元论与一元论。'),sources=['https://www.etymonline.com/word/pluralism','https://en.wiktionary.org/wiki/pluralism']),
E('triplet','/ˈtrɪplət/','三胞胎之一；三个一组；三连音','三样东西被当成一个小组；谈出生时是一胎三人中的一个，谈音乐时是三音组成一个节奏单位。','英语 triple + -et，-et 有小称、组合名词作用，早期有三行诗用法，随后扩展到三件组合、三胞胎与音乐。',A(TR,'英语 triple + -et → triplet','三行诗；三个一组；三胞胎之一、三连音'),'one of triplets 是三胞胎之一；the triplets 是三人。音乐里常将三个等值音放进通常容纳两个同类音的时值，并非所有连续三个音都叫三连音。','a set of triplets；one of the triplets；play a triplet。','triple 说三倍或三重；triplet 说组成一组的三个，或该组中的一员。',('She is the youngest of the triplets.','她是三胞胎中最小的一个。'),('The pianist practised the triplet rhythm slowly.','钢琴手慢慢练习三连音节奏。'),sources=['https://www.etymonline.com/word/triplet','https://en.wiktionary.org/wiki/triplet']),
E('pluralistic','英 /ˌplʊərəˈlɪstɪk/；美 /ˌplʊrəˈlɪstɪk/','多元的；多元主义的','环境中容得下不止一种传统、信仰或声音，各部分可以保留差异而参与共同生活。','英语 plural + -istic，与 pluralism 相应；形容词表达具有多元主义特点，而不是语法复数的普通同义词。',A(PL,'英语 plural + -istic → pluralistic','具有多元并存特点的'),'a pluralistic society 通常谈群体与观点的并存；a pluralistic approach 可说允许多种方法或解释。它不保证现实中各方已经拥有完全相等的影响。','a pluralistic society；a pluralistic approach；pluralistic values。','plural 在语法里指复数；pluralistic 常说社会或思想体系多元，不能拿来修饰普通的 books 复数形式。',('The university serves a pluralistic community with many traditions.','这所大学服务于一个拥有多种传统的多元社区。'),('The researchers adopted a pluralistic approach that combined several methods.','研究人员采取了结合多种方法的多元研究路径。'),sources=['https://en.wiktionary.org/wiki/pluralistic']),
E('doublet','/ˈdʌblət/','成对的东西；同源异形词；紧身短上衣〔服装史〕','两层或两件相配是老背景：衣服可以有双层，两个词也可能像同一祖先走出来的两条不同支线。','中古英语借古法语 doublet，是 duble“双重”的小称形式；服装义也沿这条法语路线形成，名称常联系其双层或衬里结构。',D[:1]+[['古法语 duble + -et → doublet → 中古英语 doublet','双层相关的衣服；紧身短上衣'],['英语 doublet 的扩展','成对组合；同源但形式不同的词']], '服装史中常指欧洲男性穿的贴身短上衣。词源学中 fragile 与 frail 是 doublets：都追到拉丁 fragilis，却经不同传播路径形成不同英语词形。光学里也可指两片组合的透镜。','etymological doublets；a velvet doublet；a lens doublet。','synonyms 是意思相近的词，不要求同源；doublets 关键是共同来源，现代意思可以分得很远。',('The actor wore a velvet doublet in the historical play.','演员在历史剧中穿了一件天鹅绒紧身短上衣。'),('Frail and fragile are etymological doublets.','frail 和 fragile 是同源异形词。'),sources=['https://www.etymonline.com/word/doublet','https://www.merriam-webster.com/dictionary/doublet']),
E('pluralist','英 /ˈplʊərəlɪst/；美 /ˈplʊrəlɪst/','多元主义者；兼任多个教职者〔历史〕；多元主义的','现代常说愿意给多种思想或群体留位置的人；早期却可指一个人同时坐在几个教会职位上。','英语 plural + -ist。教职义的 pluralist 记录早于 pluralism；现代可用 pluralism 来理解，却不能把所有历史都画成先有 -ism 再换 -ist。',A(PL,'英语 plural + -ist → pluralist','兼多个教职者；后来指多元主义者'),'a political pluralist 支持某种政治多元观点；a pluralist view 作定语时是多元主义的看法。具体接受哪些多元原则，要看作者论证。','a committed pluralist；a pluralist society；a pluralist view。','pluralist 常指人，也可作形容词；pluralism 指观念或制度。两者历史出现顺序不要只照后缀长短推断。',('She describes herself as a pluralist who values open debate.','她称自己是重视开放讨论的多元主义者。'),('The historian investigated the income of an eighteenth-century clerical pluralist.','历史学家调查了一位十八世纪兼任多个教职者的收入。'),sources=['https://www.etymonline.com/word/pluralism','https://en.wiktionary.org/wiki/pluralist']),
E('doubletree','/ˈdʌbəltriː/','双马牵引横木；双马平衡牵引杆','两匹马各有一根牵引横杆，再通过共同的一根横杆连接车具，帮助汇合、平衡牵引力。','英语 double 双 + tree 木材、木制构件；tree 在这种器具名里不是地里长着的一棵树。',A(D,'英语 double + tree → doubletree','供两匹马共同牵引的横杆装置'),'见于马车、农具与相关历史描写。常连接两根 singletrees，再把两匹马的拉力传向车或工具。大写商标使用不能代替这个器具义。','a wooden doubletree；attach the doubletree；a doubletree and singletrees。','singletree 通常连接单匹马的挽具；doubletree 把两套单马牵引连接起来。',('The farmer attached the two singletrees to the doubletree.','农夫把两根单马横杆连接到双马牵引横木上。'),('The museum displays a wooden doubletree beside the old wagon.','博物馆在旧货车旁展示了一根木制双马牵引横杆。'),sources=['https://www.merriam-webster.com/dictionary/doubletree','https://en.wiktionary.org/wiki/doubletree']),
E('doublespeak','/ˈdʌbəlspiːk/','故意掩饰实情的话；含混误导的说法','表面的话听起来温和、正面，真实事情却被藏在另一层，让听众不容易看出发生了什么。','英语 double + speak，二十世纪仿 Orwell 的 doublethink、Newspeak 等造词风格形成；doublespeak 这个整词并未出现在《一九八四》中。',A(D,'英语 double + speak → doublespeak〔仿 Orwell 式构词〕','两层话语；掩饰或歪曲实情的表达'),'可以通过委婉词、术语或故意模糊来回避实质。不是任何礼貌表达都是 doublespeak，批评点在语言被用来遮蔽、误导。','corporate doublespeak；political doublespeak；cut through the doublespeak。','euphemism 是委婉语，本身未必恶意；doublespeak 通常明确批评表达具有误导性。',('Employees saw the phrase voluntary departure as doublespeak for forced dismissal.','员工认为“自愿离职”只是掩饰强制解雇的说法。'),('The reporter asked a direct question to cut through the doublespeak.','记者直接发问，试图穿透那些含混误导的话。'),sources=['https://www.etymonline.com/word/doublespeak','https://en.wiktionary.org/wiki/doublespeak']),
E('doubler','英 /ˈdʌblə/；美 /ˈdʌblər/','倍增器；增倍的人或装置；加强补板','装置把某个量做成两倍，或材料再加一层形成补强；要先看究竟把什么加倍了。','主要是英语 double + -er。方言中读音、含义另有“大盘、大碗”的旧词，来自法语与后期拉丁 duplarius，不与现代装置义混作一步派生。',D+[['英语 double + -er → doubler','执行加倍或增加一层功能的人、器具'],['另支：后期拉丁 duplarius → 法语 doublier → 中古英语 dobler','大型盘、碗的方言词']], 'frequency doubler 输出的频率是输入的两倍；voltage doubler 是倍压电路。结构上的 doubler 是加强或修补板，不保证装上后强度就精确翻倍。','a frequency doubler；a voltage doubler；a doubler plate。','double 是动作或双重性质；doubler 命名执行相关作用的实体。具体工程性能不能仅从词名推算。',('The circuit uses a frequency doubler to produce the required signal.','电路用倍频器产生所需信号。'),('A metal doubler was fitted over the damaged section.','受损部位上安装了一块金属加强补板。'),sources=['https://www.merriam-webster.com/dictionary/doubler','https://en.wiktionary.org/wiki/doubler']),
]
NP=P+[['拉丁短语 non plus“不再更多、不能再前进” → 英语名词 nonplus','无话可说、无计可施的境地'],['英语名词 nonplus → 动词 nonplus','使困惑得不知道如何继续']]
W.extend([
E('nonplus','英 /ˌnɒnˈplʌs/；美 /ˌnɑːnˈplʌs/','使困惑得不知所措；无计可施的境地〔名词较旧〕','被一个问题堵在原地，脑中暂时再拿不出下一句话或下一步。','来自拉丁短语 non plus“不再、不能再往前”，先在英语中作境地名词，再转为使人陷入该境地的动词。',NP,'The question nonplussed him 是问题把他问住了。旧表达 at a nonplus 指无计可施；现代更常碰到形容词 nonplussed。这里并不是简单地“不加分”。','nonplus someone；be at a nonplus〔旧〕。','puzzle 可泛指使困惑；nonplus 常突出一时不知道说什么、做什么的停顿。',('The unexpected question nonplussed the speaker.','这个意外问题把发言者问住了。'),('The contradiction left the investigator at a nonplus.','这个矛盾让调查者一时无计可施。'),sources=['https://www.etymonline.com/word/nonplus','https://www.merriam-webster.com/dictionary/nonplus']),
E('nonplussed','英 /ˌnɒnˈplʌst/；美 /ˌnɑːnˈplʌst/','困惑得不知所措的；不为所动的〔主要美式新义〕','传统画面是思路被堵住，一时接不上；部分现代美式用法却把它理解成没被影响，读时要看上下文。','英语 nonplus 的过去分词形容词，-ed 接在 /s/ 后读 /t/。后来的“不受影响”义与传统义方向不同，不能从 non- 字面硬推。',A(NP,'英语 nonplus → nonplussed','被问住、弄糊涂；部分美式用法另指泰然不动'),'学习时先掌握“困惑、措手不及”的传统义。美式报道中也可能表示 unfazed，但这种用法仍有争议；想明确说镇定，可直接用 calm 或 unfazed。','look nonplussed；be nonplussed by；leave someone nonplussed。','unfazed 明确说不受扰动；传统 nonplussed 则是不知道怎样反应，几乎相反。',('She looked nonplussed and asked him to explain the joke.','她一脸困惑，请他解释这个笑话。'),('The surprising result left the whole team nonplussed for a moment.','出人意料的结果让整个团队一时不知所措。'),sources=['https://www.merriam-webster.com/dictionary/nonplussed','https://www.etymonline.com/word/nonplus']),
E('pluralize','英 /ˈplʊərəlaɪz/；美 /ˈplʊrəlaɪz/','把词变成复数；用复数表示','要说的已经不是单个，就给名词换上合适的复数形式；不一定只是在尾巴上加 s。','英语 plural + -ize，使成复数；英式还常拼 pluralise。',A(PL,'英语 plural + -ize → pluralize','把词改为或用作复数形式'),'pluralize city 要写 cities；pluralize child 要用 children。程序中的 pluralize 函数也做这件事，但不同语言的规则与例外不能都套英语加 s。','pluralize a noun；pluralize the word；automatically pluralize。','plural 是复数形式或性质；pluralize 是形成这个形式的动作。',('To pluralize city, change the final y to ies.','把 city 变成复数时，要把末尾 y 改为 ies。'),('The program cannot correctly pluralize every irregular noun.','程序无法把每一个不规则名词都正确变成复数。'),sources=['https://www.merriam-webster.com/dictionary/pluralize']),
E('pluralization','英 /ˌplʊərəlaɪˈzeɪʃən/；美 /ˌplʊrələˈzeɪʃən/','复数化；形成复数的过程或规则','把“怎么从一个变成复数表达”当成一个语言步骤来研究，关注的是词形怎么改。','英语 pluralize + -ation，动词变过程名词；英式拼写可用 pluralisation。',A(PL,'英语 plural → pluralize → pluralization','复数 → 使成复数 → 复数化过程'),'regular pluralization 可说规则复数变化；irregular pluralization 包括 child / children 等变化。它主要是词法问题，不是数学上把一个数乘大。','rules of pluralization；irregular pluralization；pluralization patterns。','plurality 是多个的状态或相对多数；pluralization 是变为复数的过程，词尾不同会改变关注点。',('The lesson compares regular and irregular pluralization.','这节课比较规则与不规则的复数变化。'),('Pluralization rules differ across languages.','不同语言的复数化规则并不相同。'),sources=['https://www.merriam-webster.com/dictionary/pluralization']),
E('treble','/ˈtrebəl/','三倍的；增至三倍；高音、高音声部','数量义与 triple 一样是三份；音乐义从旧时较高的声部名称走来，今天听音响时就是高频部分。','与 triple 同接拉丁 triplus，经古法语 treble 形成另一词形；动词另经 trebler。高音名词联系旧法语的第三声部称呼，不是声音真的大了三倍。',TR[:1]+[['古法语 treble → 中古英语 treble；trebler → treble〔动词〕','三倍的；使成三倍'],['盎格鲁法语 treble〔声部名词〕→ 英语 treble','较高声部 → 高音、高频部分']], 'Costs trebled 表示成本变成原来的三倍，英国英语常见。turn down the treble 是调低高频，不是把总音量减成三分之一。a treble clef 是高音谱号。','treble the amount；treble and bass；a treble clef。','triple 与 treble 在三倍义重合；普通音响里的高音通常用 treble，不能换成 triple。',('Demand trebled after the exhibition opened.','展览开幕后，需求变成了原来的三倍。'),('The recording sounds harsh, so I turned down the treble.','录音听起来刺耳，所以我调低了高音。'),sources=['https://www.etymonline.com/word/treble']),
E('triply','/ˈtrɪpli/','三倍地；三重地；从三个方面','有三份作用或三个方面一起叠上来，用副词把这种三重关系说清楚。','英语 triple + -ly，词尾 e 去掉，合成 triply；与表示绊倒、旅行的 trip 不是这里的拆分关系。',A(TR,'英语 triple + -ly → triply','以三倍或三重方式'),'triply protected 可以指有三层保护；triply difficult 也可强调三个困难因素叠加，不一定在做精确的难度测量。专业组合还要看后面具体修饰什么。','triply protected；triply important；triply reinforced。','three times 常直接说次数或数量；triply 更常放在形容词、分词前，说三重程度或方式。',('The package was triply protected by foam, cardboard, and a wooden crate.','包裹受到泡沫、纸板和木箱的三重保护。'),('The delay was triply frustrating because it wasted time, money, and effort.','这次延误既浪费时间、金钱，又浪费精力，令人倍感沮丧。'),sources=['https://www.collinsdictionary.com/dictionary/english/triply','https://www.etymonline.com/word/triple']),
])
ROOT=dict(id='C1078',meaning='更多；不止一个；相关倍数构件',core='先有一个，再想到不止一个、数量更多。plus 保留增加的方向，plural 把多个当作语法或社会特点。另把 -plus 的几倍用法放在旁边比较。',image='一个盒子旁再添东西，是 plus；不止一个盒子，是 plural；照原盒子做出同样的两份、三份、四份，是 double、triple、quadruple。',intro='拉丁 plūs 表更多，plūris 等屈折形式留下 plur-。这条线连接 plus、plural 与 surplus。double、triple、quadruple 中的拉丁 -plus 是倍数构件；其更远来源有“折叠”和“多”的不同分析，因此本页把两条历史分开，不把它们说成现代英语 plus 的直接派生。',forms='plūs 与 plūr- 是拉丁同一词的不同形式。pluralis 连接 plural，pluralitas 连接 plurality。倍数后缀 -plus 经 duplus、triplus、quadruplus 等完整拉丁词和法语路线进入英语，可见 -ble 或 -ple；doublet、doubly 则沿各自后续路径发展。',branches=[['数量更多与额外部分','plus, surplus, nonplus, nonplussed, pluperfect'],['复数、多元与相关人物','plural, plurality, pluralism, pluralist, pluralistic, pluralize, pluralization'],['两倍与双重支线','double, doubly, doublet, doubletree, doublespeak, doubler'],['三倍、四倍与三件组合','triple, triplet, triply, treble, quadruple']],contrasts='plurality 在投票中可只是比任何另一组多，majority 通常要求过半。pluralization 是形成复数，plurality 是多个的状态。triple 和 treble 在三倍义相通，treble 另有高音义。nonplussed 的传统义是被弄糊涂，部分美式新义却是不受影响，需看语境。',practice='The output doubled, but the price remained the same—a clear plus. 产出变成两倍，价格却没变，这是明显的优点。double 说倍数关系，plus 说多出来的好处；理解它们不需要假装两词有相同的现代构词步骤。',words=[],exclude={})
if __name__=='__main__':
    m=json.loads((BASE/'.cache/batch200/rewrite_vid.json').read_text());r=next(r for r in m['roots'] if r['id']==ROOT['id'])
    ROOT['words']=[w for w in r['family'] if '-' not in w]
    expected=(set(ROOT['words'])&set(m['owned_words']))-{'surplus'};actual={e['word'] for e in W}
    assert actual==expected,(expected-actual,actual-expected)
    assert len(W)==len(actual) and all(len(e['examples'])>=2 and len(e['history'])>=2 for e in W)
    OUT.mkdir(parents=True,exist_ok=True)
    (OUT/'roots_batch200_vid_18.json').write_text(json.dumps([ROOT],ensure_ascii=False,indent=2))
    (OUT/'words_batch200_vid_18.json').write_text(json.dumps(W,ensure_ascii=False,indent=2))
    print('plur:',len(W),'words;',sum(len(x['examples']) for x in W),'examples;',len(ROOT['words']),'references')
